import{_ as o,a as e,b as a}from"./chunks/bind_id.cROGXoYi.js";import{_ as r,o as i,c as n,a0 as s}from"./chunks/framework.DRjqbEpm.js";const b=JSON.parse('{"title":"3. 適應引擎：訓練新網站","description":"","frontmatter":{},"headers":[],"relativePath":"guide/adaptive-engine.md","filePath":"guide/adaptive-engine.md"}'),l={name:"guide/adaptive-engine.md"};function d(c,t,g,_,p,u){return i(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="_3-適應引擎-訓練新網站" tabindex="-1">3. 適應引擎：訓練新網站 <a class="header-anchor" href="#_3-適應引擎-訓練新網站" aria-label="Permalink to &quot;3. 適應引擎：訓練新網站&quot;">​</a></h1><p>如果遇到 V-Train 無法自動識別的影音網站，您可以透過獨家的「適應引擎 (Adaptive Engine)」親自訓練它！</p><blockquote><p><img src="'+o+'" alt="訓練模式概覽"></p></blockquote><h3 id="訓練步驟" tabindex="-1">訓練步驟： <a class="header-anchor" href="#訓練步驟" aria-label="Permalink to &quot;訓練步驟：&quot;">​</a></h3><ol><li><strong>啟動引擎</strong>：在目標網站上，對著<strong>任何一個影片縮圖點擊「右鍵」</strong>，然後在左下角的 V-Train 面板選擇要存入的模組 (Mod 1 ~ Mod 4)。</li><li><strong>視覺化捕捉 (Visual Capture)</strong>： <blockquote><p><img src="'+e+'" alt="視覺化捕捉框"> 畫面會出現一個綠色或紅色的選取框。</p></blockquote><ul><li>使用鍵盤的 <strong><code>↑</code> (上) / <code>↓</code> (下)</strong> 鍵來擴張或縮小選取範圍。</li><li>請確保選取框<strong>剛好包覆住整張縮圖圖片</strong>，不要選到外層的文字標題。</li><li>調整完畢後按下 <strong><code>Enter</code></strong> 確認。</li></ul></li><li><strong>輸入正片網址</strong>：點擊該縮圖進入播放頁面，將網址列的完整 URL 複製並貼上到 V-Train 面板中。</li><li><strong>綁定 ID</strong>：系統會分析網址並列出可能的 ID 片段。請點選最像「影片唯一編號」的那一段。 <blockquote><p><img src="'+a+'" alt="綁定ID"></p></blockquote></li><li><strong>完成訓練</strong>：點擊儲存，現在回到首頁，您就會發現該網站的所有影片都已經成功掛上進度條了！</li></ol>',5)])])}const f=r(l,[["render",d]]);export{b as __pageData,f as default};
